// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/chats", wrapper.ListChats)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/chats", wrapper.CreateChat)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/chats/{chat_id}", wrapper.DeleteChat)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/chats/{chat_id}", wrapper.GetChat)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/chats/{chat_id}", wrapper.UpdateChat)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/chats/{chat_id}/nodes/{node_id}", wrapper.EditNodeTask)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/chats/{chat_id}/nodes/{node_id}/queue", wrapper.QueueNodeMessage)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/chats/{chat_id}/nodes/{node_id}/queue/{message_id}", wrapper.RemoveQueuedMessage)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/chats/{chat_id}/nodes/{node_id}/queue/{message_id}", wrapper.EditQueuedMessage)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/chats/{chat_id}/nodes/{node_id}/status", wrapper.UpdateNodeStatus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/chats/{chat_id}/recording", wrapper.GetChatRecording)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/chats/{chat_id}/responses", wrapper.SendChatMessage)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/chats/{chat_id}/responses/{response_id}", wrapper.GetResponse)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/chats/{chat_id}/responses/{response_id}/status", wrapper.UpdateResponseStatus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/chats/{chat_id}/stream", wrapper.SubscribeChatStream)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/memories", wrapper.ListMemories)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/memories/{memory_id}", wrapper.DeleteMemory)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/recordings", wrapper.ListRecordings)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/health", wrapper.HealthCheck)
	})

	return r
}
